"""
    Gets the root of a url

    Inputs:
    link - the url of the page

    Output:
    Returns the root of the link if it can fint it. Otherwise, returns -1.
    """
def get_link_root(link: Any) -> object {
    websites = ["com", "org", "net", "int", "edu", "gov", "mil"];
    for extension in websites {
        index = link.find(extension);
        if (index != -1) {
            return (link[0:(index + 3)] + "/");
        }
    }
    return "-1";
}

""" expand the segment"""
def expand_segment(
    num_frames: Any, num_target_frames: Any, start_frame: Any, stop_frame: Any
) -> object {
    num_frames_seg = (stop_frame - start_frame) + 1;
    changes = False;
    num_target_frames = min(num_target_frames, num_frames);
    if (num_frames_seg < num_target_frames) {
        while True {
            if (start_frame > 0) {
                start_frame -= 1;
                num_frames_seg += 1;
                changes = True;
            }
            if (num_frames_seg == num_target_frames) {
                break;
            }
            if (stop_frame < (num_frames - 1)) {
                stop_frame += 1;
                num_frames_seg += 1;
                changes = True;
            }
            if (num_frames_seg == num_target_frames) {
                break;
            }
        }
    }
    return (start_frame, stop_frame, changes);
}

