"""Converts height in cm to m/cm."""
def height_to_metric(height: Any) -> object {
    meters = int(height) // 100;
    centimeters = height % 100;
    return (meters, centimeters);
}

""" return alpha based on z depth """
def zalpha(z: Any, zmin: Any, zrng: Any, a_min: Any = 0) -> object {
    alpha = a_min + (((1 - a_min) * (z - zmin)) / zrng);
    return alpha;
}

"""Returns the key that may be used to sort benchmarks by label."""
